@MainActor
private final class ColumnProbe: NSObject {
    private weak var gallery: UITableView?
    private var link: CADisplayLink?
    private var update: ((Double) -> Void)?
    private var startTime = 0.0
    private var previous = 0.0
    private var tick = 0
    private var firstQueries = 0
    private var firstCPU = 0.0
    private var firstMemory: UInt64 = 0
    private var intervals: [Double] = []
    private let duration = Double(ProcessInfo.processInfo.environment["NEXA_BENCH_SECONDS"] ?? "") ?? 5
    private var nextMemorySample = 5.0
    private var memorySamples: [UInt64] = []

    func start(_ update: @escaping (Double) -> Void) {
        guard link == nil else { return }
        self.update = update
        intervals.reserveCapacity(Int(duration * 70))
        let link = CADisplayLink(target: self, selector: #selector(frame(_:)))
        link.preferredFramesPerSecond = 60
        link.add(to: .main, forMode: .common)
        self.link = link
    }

    func stop() {
        link?.invalidate()
        link = nil
        update = nil
    }

    @objc private func frame(_ link: CADisplayLink) {
        let now = CACurrentMediaTime()
        if startTime == 0 { startTime = now + 2 }
        if now >= startTime {
            if previous == 0 {
                firstQueries = nexaBenchQueries
                firstCPU = cpuSeconds()
                firstMemory = residentBytes()
            } else {
                intervals.append((now - previous) * 1000)
            }
            previous = now
            if duration > 5, now - startTime >= nextMemorySample {
                memorySamples.append(residentBytes())
                nextMemorySample += 5
            }
            if now - startTime >= duration {
                let sorted = intervals.sorted()
                let result: [String: Any] = [
                    "wallSeconds": now - startTime,
                    "leadingRowQueries": nexaBenchQueries - firstQueries,
                    "cpuSeconds": cpuSeconds() - firstCPU,
                    "residentBytesStart": firstMemory,
                    "residentBytesEnd": residentBytes(),
                    "residentBytesEveryFiveSeconds": memorySamples,
                    "displayLinkIntervals": intervals.count,
                    "displayLinkP95Ms": sorted[sorted.count * 95 / 100]
                ]
                let file = URL.documentsDirectory.appending(path: "column-perf.json")
                if let bytes = try? JSONSerialization.data(withJSONObject: result) {
                    try? bytes.write(to: file, options: .atomic)
                }
                stop()
                return
            }
        }
        tick += 1
        if gallery == nil {
            gallery = UIApplication.shared.connectedScenes.compactMap { ($0 as? UIWindowScene)?.keyWindow }.compactMap { findGallery($0) }.first
        }
        if let gallery {
            let maximum = max(0, gallery.contentSize.height - gallery.bounds.height)
            gallery.contentOffset.y = min(maximum, CGFloat(tick) * 10)
            gallery.layoutIfNeeded()
        }
        update?(tick.isMultiple(of: 2) ? 8 : 10)
    }

    private func findGallery(_ root: UIView) -> UITableView? {
        if let gallery = root as? UITableView { return gallery }
        for child in root.subviews {
            if let gallery = findGallery(child) { return gallery }
        }
        return nil
    }

    private func cpuSeconds() -> Double {
        var usage = rusage()
        getrusage(RUSAGE_SELF, &usage)
        return Double(usage.ru_utime.tv_sec + usage.ru_stime.tv_sec)
          + Double(usage.ru_utime.tv_usec + usage.ru_stime.tv_usec) / 1_000_000
    }

    private func residentBytes() -> UInt64 {
        var info = mach_task_basic_info()
        var count = mach_msg_type_number_t(MemoryLayout<mach_task_basic_info>.size / MemoryLayout<integer_t>.size)
        let status = withUnsafeMutablePointer(to: &info) {
            $0.withMemoryRebound(to: integer_t.self, capacity: Int(count)) {
                task_info(mach_task_self_, task_flavor_t(MACH_TASK_BASIC_INFO), $0, &count)
            }
        }
        return status == KERN_SUCCESS ? info.resident_size : 0
    }
}
